; loop.asm -- chapter 7: WHERE IT BREAKS: the count that never ends
; generated by gen07.py
        INCLUDE "msx.inc"
        OUTPUT "loop.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
init:   di
        ld sp, SYS_AREA
        ld a, 1
        or a                    ; Z = 0: A is not 0
        ld bc, 3                ; three turns
count:  dec bc                  ; BC - 1, and no flag changes
        jr nz, count            ; Z is still OR A's: round again
done:   jr done                 ; never reached
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
